test('deal names allow empty text, spaces and Unicode within forty UTF-16 code units', () => {
  assert.equal(DEAL_NAME_MAX_LENGTH, 40);
  for (const value of ['', ' ', ' Café ', 'a'.repeat(40), '😀'.repeat(20), '\tCafé\u2028'])
